def embedded_recipes() -> list:
    """The verified per-task recipe table (xz + base85, see EMBEDDED_RECIPES at the end of this file)."""
    import lzma
    data = json.loads(lzma.decompress(base64.b85decode(''.join(EMBEDDED_RECIPES.split()))))
    for r in data:
        r['non_central_artifacts'] = [{'path': p, 'sha256': h, 'bytes': n} for p, h, n in r.pop('vendored')]
    for row in data:
        row.update(RECIPE_OVERRIDES.get(row['task_id'], {}))
    return data


EMBEDDED_FIELDS = ('task_id', 'language', 'project', 'bug_id', 'repository', 'commit', 'parent', 'environment',
                   'target_file', 'file_before_sha256', 'file_after_sha256', 'fix_is_local', 'buggy_builds',
                   'image', 'setup_shell', 'build_shell', 'classification',
                   'buggy_commit', 'analyzer')


def embed_verified(a) -> None:
    """Fold the verified cache of a run (cache/verified/*.json plus the artifacts healing added)
    back into EMBEDDED_RECIPES of this very file: the recipe that proved each task, its parent
    commit, the environment it stands on, and whether the upstream fix compiles there."""
    import lzma
    rows = {r['task_id']: r for r in embedded_recipes()}
    additions = json.loads(a.vendor_additions.read_text()) if a.vendor_additions.exists() else {}
    folded = collections.Counter()
    for path in sorted((a.cache_dir / 'verified').glob('*.json')):
        rec = json.loads(path.read_text())
        row = rows.get(rec.get('task_id'))
        if row is None or not str(rec.get('status', '')).startswith('verified') or rec.get('fresh_cache_check') != 'passed':
            folded['skipped'] += 1; continue
        p = rec['proposal']
        recipe = {'image': p.get('image'), 'setup_shell': p.get('setup_shell') or '', 'build_shell': p['build_shell'],
                  'classification': p.get('classification') or 'exact_environment'}
        if any(row.get(k) != v for k, v in recipe.items()):
            folded['recipe_changed'] += 1
        row.update(recipe)
        if rec.get('repository'):
            row['repository'] = rec['repository']
        row['parent'] = rec.get('parent') or row.get('parent') or ''
        row['environment'] = p.get('environment') or 'parent'
        row['fix_is_local'] = bool(p.get('fix_is_local', True)); row['buggy_builds'] = bool(p.get('buggy_builds', True))
        # by path: two paths may hold the same content (table entries take precedence over healing additions)
        by_sha = {x['path']: x for x in additions.get(row['task_id'], []) + row.get('non_central_artifacts', [])}
        proven = set(rec.get('vendored') or [])
        artifacts = [x for x in by_sha.values() if not proven or x['path'] in proven]
        if {x['path'] for x in artifacts} != proven:
            raise ValueError(f'{row["task_id"]}: proof used artifacts the table cannot name: {sorted(proven - {x["path"] for x in artifacts})[:3]}')
        if len(artifacts) != len(row.get('non_central_artifacts', [])):
            folded['artifacts_changed'] += 1
        row['non_central_artifacts'] = sorted(artifacts, key=lambda x: x['path'])
        folded['environment=' + row['environment']] += 1; folded['fix_is_local=' + str(row['fix_is_local'])] += 1
        folded['folded'] += 1
    count = write_embedded_recipes(rows)
    print(f'embedded {count} rows into {Path(__file__).name}: ' + ', '.join(f'{k}={v}' for k, v in sorted(folded.items())), flush=True)


def write_embedded_recipes(rows: dict) -> int:
    """Replace EMBEDDED_RECIPES of this very file with these per-task rows (task_id -> row)."""
    import lzma
    out = []
    for r in sorted(rows.values(), key=lambda r: r['task_id']):
        d = {k: r.get(k) for k in EMBEDDED_FIELDS if r.get(k) is not None}
        d['vendored'] = [[x['path'], x['sha256'], x['bytes']] for x in sorted(r.get('non_central_artifacts', []), key=lambda x: x['path'])]
        out.append(d)
    blob = base64.b85encode(lzma.compress(json.dumps(out, sort_keys=True, separators=(',', ':')).encode(), preset=9 | lzma.PRESET_EXTREME)).decode()
    text = '\n'.join(blob[i:i + 100] for i in range(0, len(blob), 100))
    me = Path(__file__).resolve(); source = me.read_text()
    head, sep, rest = source.partition("EMBEDDED_RECIPES = '''\n")
    body, sep2, tail = rest.partition("\n'''\n")
    if not sep or not sep2:
        raise ValueError('cannot find the EMBEDDED_RECIPES block')
    me.write_text(head + sep + text + sep2 + tail)
    return len(out)


def load_recipes(path: Path | None):
    """Return (per-task rows, per-project distinct proposals). Default: the embedded table."""
    rows = {r['task_id']: r for r in (records(path) if path else embedded_recipes())}
    projects = collections.defaultdict(dict)
    for r in rows.values():
        pr = {k: r.get(k) for k in RECIPE_KEYS}; pr['rationale'] = r.get('rationale', ''); pr['repository'] = None
        projects[(r['language'], r['project'])].setdefault(digest({k: pr[k] for k in RECIPE_KEYS}), pr)
    return rows, {k: list(v.values()) for k, v in projects.items()}


def row_proposal(row: dict) -> dict:
    proposal = {'image': row.get('image'), 'setup_shell': row.get('setup_shell') or '', 'build_shell': row['build_shell'],
                'classification': row.get('classification') or 'exact_environment', 'rationale': row.get('rationale', ''), 'repository': None}
    for k in ('environment', 'fix_is_local', 'buggy_builds'):   # proven facts, used when packaging from the table
        if row.get(k) is not None:
            proposal[k] = row[k]
    return proposal


