                if actual is not None and actual!=source and lossy_text(actual)==lossy_text(source) and actual.count(b'\n')==source.count(b'\n'):
                    v['snapshot_match']='lossy';v['snapshot_matches_fixture']=True;source=actual
                if not v['snapshot_matches_fixture']:v['status']='snapshot_target_mismatch';continue
                if lang=='java':warning_audit_strip_formatters(work/'workspace')
                if lang=='java':
                    for properties in (work/'workspace').rglob('maven-wrapper.properties'):
                        properties.write_text(properties.read_text().replace('https://repo1.maven.org/maven2/', 'https://repo.maven.apache.org/maven2/'))
                # A setup step may already run the Maven wrapper: seed its pinned distribution first.
                if lang=='java' and args.vendor_cache and 'mvnw' in meta['recipe']['setup_shell']+meta['recipe']['build_shell']:
                    try:v['wrapper_distributions_presetup']=warning_audit_wrapper_cache(work,args.vendor_cache,dest)
                    except (OSError,RuntimeError,ValueError) as exc:
                        v['status']='wrapper_dependency_failed';v['error']=str(exc);continue
                if not stage('setup','bash /tests/build_setup.sh /workspace'):continue
                if lang=='java':
                    if args.vendor_cache and 'mvnw' in meta['recipe']['build_shell']:
                        try:v['wrapper_distributions']=warning_audit_wrapper_cache(work,args.vendor_cache,dest)
                        except (OSError,RuntimeError,ValueError) as exc:
                            v['status']='wrapper_dependency_failed';v['error']=str(exc);continue
                    if not stage('capture','bash /fixture/capture.sh'):
                        capture_status=v['status']
                        if stage('build','bash /tests/build.original.sh /workspace'):v['build_ok']=True;v['status']=capture_status
                        continue
                    v['build_ok']=True
                    database=dest/'infer-out/results.db'
                    if not database.exists():v['status']='no_capture_database';continue
                    (dest/'changed.txt').write_text('/workspace/'+target+'\n')
                    cap=sqlite3.connect(database)
                    if 'proc_name_hum' in {row[1] for row in cap.execute('PRAGMA table_info(procedures)')}:
                        procedures=cap.execute('SELECT proc_name_hum,source_file,cfg IS NOT NULL FROM procedures').fetchall();cap.close()
                        captured=[(p,f,c) for p,f,c in procedures if c and warning_audit_file(target,f)]
                        # Analyze the file Infer captured: a preprocessed copy may stand in for the source.
                        if captured:(dest/'changed.txt').write_text(''.join(sorted({'/workspace/'+f+'\n' for p,f,c in captured})))
                        v['target_procedures']=captured
                        v['target_method_captured']=any(warning_audit_method(p)==warning_audit_method(meta['expected_warning']['procedure']) for p,f,c in captured)
                        if not captured or (variant=='before' and not v['target_method_captured']):v['status']='target_not_captured';continue
                    else:
                        # Infer >=1.0 keeps procedure names/files only in marshalled attributes: read its
                        # debug inventory. Written to its own file: stage logs are capped at 2 MB, and a
                        # large inventory lost its middle (false 'target not captured').
                        cap.close()
                        if not stage('capture_inventory','infer debug --procedures --procedures-name -o /audit/infer-out > /audit/capture_inventory.full'):continue
                        inventory=dest/'capture_inventory.full'
                        v['capture_inventory_bytes']=inventory.stat().st_size
                        procedures=warning_audit_captured_procedures(inventory.read_text(errors='replace'))
                        captured=[(p,f,c) for p,f,c in procedures if warning_audit_file(target,f)]
                        v['target_capture_check']='infer_debug_defined_procedures'
                        v['target_procedures']=captured
                        v['target_method_captured']=any(warning_audit_method(p)==warning_audit_method(meta['expected_warning']['procedure']) for p,f,c in captured)
                        if not captured or (variant=='before' and not v['target_method_captured']):v['status']='target_not_captured';continue
                        (dest/'changed.txt').write_text(''.join(sorted({'/workspace/'+f+'\n' for p,f,c in captured})))
                        inventory.unlink()
                    if not stage('analyze','infer analyze -j 1 --racerd --racerd-guardedby --immutable-cast --printf-args --changed-files-index /audit/changed.txt -o /audit/infer-out'):continue
                else:
                    build_started=time.time()-2
                    if not stage('build','bash /fixture/csharp-build.sh'):continue
                    v['build_ok']=True
                    chosen,holds_target,v_assemblies=warning_audit_assemblies((work/'workspace',work/'tmp'),target,build_started,work/'workspace/.audit-binaries',work)
                    v.update(v_assemblies)
                    names_target=lambda p:p in holds_target
                    if not chosen:v['status']='no_assemblies';continue
                    if args.legacy_infersharp:
                        # InferSharp <=1.2 (biabduction: NULL_DEREFERENCE, DOTNET_RESOURCE_LEAK) ships its engine
                        # in the image; run its own run_infersharp.sh steps, with the issue types it enables.
                        analyzer_image=Path(args.legacy_infersharp)
